/**
 * Attribute the bytes of built JS chunks to their source modules
 * (Phase 11, M10 / D9). Measure first, then optimize.
 *
 *   NEXT_SOURCEMAPS=1 BACKEND_ORIGIN=http://localhost:8000 npx next build
 *   node scripts/bundle-attribution.mjs 0542cuk_va8g1.js 1d3j3764a9f0s.js ...
 *   node scripts/bundle-attribution.mjs --all        # every chunk
 *
 * Output: per source module, the approximate number of generated bytes it
 * accounts for (from source-map segments), grouped by package / app folder.
 * Uses `source-map-js`, already present in node_modules (a transitive
 * dependency) -- nothing is installed for this.
 */
import { readFileSync, readdirSync, existsSync } from "node:fs";
import { join } from "node:path";
import { SourceMapConsumer } from "source-map-js";

const dir = ".next/static/chunks";
const args = process.argv.slice(2);
const files = args[0] === "--all" ? readdirSync(dir).filter((f) => f.endsWith(".js")) : args;

function group(source) {
  const s = source.replace(/^.*?\/(node_modules|\.\.\/)/, "$1");
  const nm = /node_modules\/((?:@[^/]+\/)?[^/]+)/.exec(source);
  if (nm) return `pkg:${nm[1]}`;
  const app = /(app|components|lib)\/[^?]*/.exec(source);
  return app ? `src:${app[0]}` : `other:${s.slice(0, 60)}`;
}

const totals = new Map();
for (const file of files) {
  const js = readFileSync(join(dir, file), "utf8");
  // Turbopack names maps by their own hash and links them from the chunk.
  const ref = /\/\/# sourceMappingURL=(\S+)\s*$/.exec(js)?.[1];
  const mapPath = join(dir, ref ?? `${file}.map`);
  if (!existsSync(mapPath)) {
    totals.set(`(no map) ${file}`, (totals.get(`(no map) ${file}`) ?? 0) + js.length);
    continue;
  }
  const consumer = new SourceMapConsumer(JSON.parse(readFileSync(mapPath, "utf8")));
  const lines = js.split("\n");
  let prev = null;
  consumer.eachMapping((m) => {
    if (prev && prev.generatedLine === m.generatedLine) {
      const bytes = m.generatedColumn - prev.generatedColumn;
      const key = prev.source ? group(prev.source) : "(unmapped)";
      totals.set(key, (totals.get(key) ?? 0) + bytes);
    } else if (prev) {
      const rest = (lines[prev.generatedLine - 1]?.length ?? 0) - prev.generatedColumn;
      const key = prev.source ? group(prev.source) : "(unmapped)";
      totals.set(key, (totals.get(key) ?? 0) + Math.max(rest, 0));
    }
    prev = m;
  });
}
const rows = [...totals.entries()].sort((a, b) => b[1] - a[1]);
const sum = rows.reduce((a, [, b]) => a + b, 0);
for (const [k, v] of rows.slice(0, 40)) console.log(`${String(v).padStart(8)}  ${((v / sum) * 100).toFixed(1).padStart(5)}%  ${k}`);
console.log(`${String(sum).padStart(8)}  total mapped bytes (uncompressed)`);
